import importlib, shutil, sys

for mod in ["z3", "sympy", "pytest", "hypothesis"]:
    try:
        m = importlib.import_module(mod)
        print(f"{mod:12s} AVAILABLE  {getattr(m, '__version__', '?')}")
    except ImportError as e:
        print(f"{mod:12s} MISSING    ({e})")

print()
for exe in ["coqc", "lean", "isabelle", "z3", "cvc5", "why3"]:
    print(f"{exe:9s} -> {shutil.which(exe)}")
print()
print("python:", sys.version.split()[0])
